// One row per hotel: lowest price, official site price, gap and the sites cheaper than the official site.
const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .map((i) => i.json)
  .filter((h) => h.found !== false)
  .map((h) => {
    const official = h.officialSitePrice;
    const cheaper = official == null ? [] : (h.sites ?? []).filter((s) => !s.officialSite && s.price < official);
    return {
      json: {
        checkedOn: today,
        hotel: h.name,
        checkIn: h.checkIn,
        currency: h.currency,
        lowestPrice: h.lowestPrice,
        lowestPriceSite: h.lowestPriceSite,
        officialSitePrice: official,
        officialVsLowestPercent: official && h.lowestPrice ? Math.round(((official - h.lowestPrice) / h.lowestPrice) * 1000) / 10 : null,
        cheaperThanOfficial: cheaper.map((s) => `${s.site} ${s.price}`).join(', '),
        sitesCount: h.sitesCount,
        cheapestUpcomingNight: h.calendarLowestPriceCheckIn,
        cheapestUpcomingPrice: h.calendarLowestPrice,
        googleHotelsUrl: h.googleHotelsUrl,
      },
    };
  });
